{
  "name": "realtime-agent",
  "version": "0.1.0",
  "private": true,
  "type": "module",
  "workspaces": [
    "src/agent",
    "src/vscode-extension"
  ],
  "scripts": {
    "build": "npm run build:agent && npm run build:vscode-extension",
    "test": "npm run test:agent && npm run test:vscode-extension",
    "build:agent": "npm run build --workspace realtime-agent-lib",
    "test:agent": "npm run test --workspace realtime-agent-lib",
    "build:vscode-extension": "npm run build --workspace sheaf-vscode-extension",
    "test:vscode-extension": "npm run test --workspace sheaf-vscode-extension",
    "clean": "npm run clean --workspace realtime-agent-lib && npm run clean --workspace sheaf-vscode-extension && rm -rf node_modules"
  },
  "engines": {
    "node": ">=20"
  }
}
{
  "name": "realtime-agent-lib",
  "version": "0.1.0",
  "description": "Realtime agent library and CLI for OpenAI Realtime API experimentation",
  "type": "module",
  "main": "./dist/src/agent/src/index.js",
  "types": "./dist/src/agent/src/index.d.ts",
  "exports": {
    ".": {
      "types": "./dist/src/agent/src/index.d.ts",
      "import": "./dist/src/agent/src/index.js",
      "require": "./dist/src/agent/src/index.js"
    }
  },
  "bin": {
    "realtime-agent": "./dist/src/agent/src/cli.js"
  },
  "files": [
    "dist"
  ],
  "scripts": {
    "build": "tsc -p tsconfig.json",
    "test": "npm run build && node scripts/run-agent-tests.mjs",
    "clean": "rm -rf dist node_modules",
    "prepack": "npm run build"
  },
  "engines": {
    "node": ">=20"
  },
  "devDependencies": {
    "@types/better-sqlite3": "^7.6.13",
    "@types/node": "^22.15.21",
    "@types/ws": "^8.18.1",
    "typescript": "^5.8.3"
  },
  "dependencies": {
    "better-sqlite3": "^12.10.0",
    "naudiodon": "^2.3.6",
    "ws": "^8.21.0"
  }
}
{
  "name": "sheaf-vscode-extension",
  "displayName": "Sheaf",
  "description": "Voice-driven realtime agent for VS Code (Sheaf)",
  "version": "0.0.1",
  "publisher": "sheaf",
  "private": true,
  "engines": {
    "vscode": "^1.85.0"
  },
  "categories": [
    "Other"
  ],
  "activationEvents": [
    "onCommand:sheaf.realtime.toggleSession",
    "onCommand:sheaf.realtime.commitAndRespond",
    "onView:sheaf.chatView"
  ],
  "main": "./out/extension.js",
  "contributes": {
    "viewsContainers": {
      "activitybar": [
        {
          "id": "sheafContainer",
          "title": "Sheaf",
          "icon": "media/sheaf.svg"
        }
      ]
    },
    "views": {
      "sheafContainer": [
        {
          "id": "sheaf.chatView",
          "name": "Realtime Chat",
          "type": "webview"
        }
      ]
    },
    "commands": [
      {
        "command": "sheaf.realtime.toggleSession",
        "title": "Sheaf: Toggle Realtime Session"
      },
      {
        "command": "sheaf.realtime.commitAndRespond",
        "title": "Sheaf: Commit Audio And Request Response"
      }
    ],
    "keybindings": [
      {
        "command": "sheaf.realtime.toggleSession",
        "key": "f16"
      },
      {
        "command": "sheaf.realtime.commitAndRespond",
        "key": "f20"
      }
    ],
    "configuration": {
      "title": "Sheaf Realtime",
      "properties": {
        "sheaf.realtime.openAiApiKey": {
          "type": "string",
          "default": "",
          "description": "OpenAI API key (optional if stored in VS Code Secret Storage or config/api_keys.json)."
        },
        "sheaf.realtime.model": {
          "type": "string",
          "default": "gpt-realtime-2"
        },
        "sheaf.realtime.systemPrompt": {
          "type": "string",
          "default": "",
          "description": "Overrides the built-in sheaf VS Code system prompt when non-empty."
        },
        "sheaf.realtime.inputDevice": {
          "type": "string",
          "default": "",
          "description": "Optional microphone device id or substring (see realtime-agent list-input-devices)."
        },
        "sheaf.realtime.safetyIdentifier": {
          "type": "string",
          "default": "",
          "description": "Optional safety identifier header for OpenAI Realtime."
        }
      }
    }
  },
  "scripts": {
    "build": "node esbuild.config.mjs",
    "dev": "node esbuild.config.mjs --watch",
    "lint": "tsc -p tsconfig.json --noEmit",
    "test": "rm -rf .test-dist && tsc -p tsconfig.test.json && node scripts/run-vscode-extension-tests.mjs",
    "clean": "rm -rf out .test-dist node_modules *.vsix"
  },
  "dependencies": {
    "better-sqlite3": "^12.10.0",
    "naudiodon": "^2.3.6",
    "realtime-agent-lib": "*"
  },
  "devDependencies": {
    "@types/node": "^22.10.1",
    "@types/vscode": "^1.85.0",
    "esbuild": "^0.24.0",
    "typescript": "^5.7.2"
  }
}
